<template><view><view class="follow-card"><image :src="media(post.thumbnail)" mode="aspectFill"/><view><text class="brand">crow look粉红乌鸦</text><text class="slogan">因为我黑，所以一闭眼就会想起我</text></view><button @click="follow">关注</button></view><view class="contact"><view class="line"><view class="label"><CrowIcon name="chat-o"/>微信</view><view class="value">Crowlook <text class="pink" @click="service">♧ 添加客服</text></view></view><view class="line address"><view class="label"><CrowIcon name="location-o"/>地址</view><view class="value"><view v-for="s in config.site_add" :key="s.nam" class="store"><text @click="openStores">{{s.nam}}：{{s.add}}</text><text class="phone" @click="copyPhone(s)"><CrowIcon name="phone"/>{{s.tel}}</text></view></view></view></view><CommentList v-if="post.comments?.length" class="article-comments" :comments="post.comments"/><view v-if="post.related?.length" class="related"><view class="related-heading"><text>猜你喜欢</text><text class="likes">{{Number(post.fav_count||0)+(liked?1:0)}}人喜欢</text></view><view class="related-grid" :class="{news:isArticle}"><view v-for="p in post.related" :key="p.id" @click="go(p)"><image :src="media(p.thumbnail)" mode="aspectFill"/><text>{{p.title}}</text></view></view></view></view></template>
<script setup>import {config,media,go,service} from '../lib/content';import CrowIcon from './CrowIcon.vue';import CommentList from './CommentList.vue';defineProps({post:Object,isArticle:Boolean,liked:Boolean});const follow=()=>uni.previewImage({urls:['/static/contact/wechat.jpg']});const openStores=()=>uni.navigateTo({url:'/pages/locations/locations'});const copyPhone=s=>uni.setClipboardData({data:s.tel})</script>
